INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IN_ORDER_TO_INCREASE","Afin d'élargir le réseau de revendeurs et la géographie d'expédition des équipements pour restaurants, bars et cafés, nous invitons les entreprises à devenir nos revendeurs pour une coopération à long terme. Nous sommes heureux de vous offrir un système de remises individuelles, des conditions de livraison et de paiement pratiques, une gamme de services de transport et de logistique, un accès à des informations techniques et des produits promotionnels. Les entreprises participant aux achats publics se voient proposer des programmes de bonus pour augmenter les remises des concessionnaires.");
