INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_COUNTRY_HELP","Il n'y a aucune information sur le pays d'enregistrement de votre compte dans notre système de compte. Contactez votre responsable pour attribuer le pays à votre contrepartie.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_VERIFIED_TEXT","E-mail non confirmé.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_VERIFIED_HELP","Vous n'avez pas encore confirmé votre email. Afin de confirmer l'inscription, cliquez sur le lien dans l'e-mail qui vous a été envoyé après l'inscription. Veuillez vérifier les messages entrants ainsi que le dossier Spam. Vous pouvez également demander à nouveau le lien de confirmation; veuillez vous rendre sur la page:");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_CONFIRMED_DIRECTOR_TEXT","Le compte est désactivé par votre superviseur.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_CONFIRMED_DIRECTOR_HELP","Votre compte a été désactivé. Pour plus d’informations, contactez votre superviseur.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_PORTAL_CONFIRMER_TEXT","Le compte n'a pas été confirmé par le gestionnaire.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_PORTAL_CONFIRMER_HELP","Le gestionnaire a déjà été informé de votre inscription et doit la confirmer afin de vous offrir un accès complet au portail. S'il vous plaît, attendez. Vous pouvez contacter votre responsable pour accélérer la procédure.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ACTIVE_TEXT","Le compte est désactivé.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ACTIVE_HELP","Votre compte a été désactivé. Pour plus d’informations, contactez votre responsable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ENTITY_TEXT","Il n'y a pas d'entité juridique dans le système comptable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ENTITY_HELP","Il n'y a aucune information sur votre entité juridique dans notre système comptable. Si vous êtes une nouvelle contrepartie et que vous avez signé un contrat aujourd'hui, ces informations n'apparaîtront dans le système que demain. Si la notification ne disparaît pas dans la journée, veuillez contacter votre responsable pour corriger l'erreur.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_PRICELIST_TEXT","Aucune liste de prix n'est attribuée dans le système comptable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_PRICELIST_HELP","Il n'y a aucune information sur les conditions de votre concessionnaire dans notre système comptable. Contactez votre responsable pour vous attribuer une grille tarifaire.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"YOUR_ACCOUNT_HAS_ERRORS","Votre compte contient des erreurs");
