INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ACTIVE_DEALER_TEXT","La contrepartie est désactivée dans le système comptable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ACTIVE_DEALER_HELP","Votre compte contrepartie a été désactivé. Pour plus d’informations, veuillez contacter votre responsable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_SALES_TYPES_TEXT","Il n'y a pas de direction des ventes dans le système comptable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_SALES_TYPES_HELP","Notre système comptable ne contient aucune information sur la direction des ventes de votre compte. Contactez votre responsable pour attribuer une direction commerciale à votre contrepartie.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"DEALERS_API_DOC","Documentation de l'API des concessionnaires");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"API_SUPERVISOR_ROLE_REQUIRED","Vous devez disposer d'un compte avec le rôle \"Superviseur\" pour générer la clé API. Si votre entreprise ne dispose pas encore d'un tel compte, contactez votre responsable. Si vous avez seulement besoin de créer une clé API pour son utilisation ultérieure et que votre entreprise dispose d'un compte «Superviseur», contactez son propriétaire.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"API_API_KEY_WARNING","En générant et en utilisant la clé API, vous confirmez votre accord avec les conditions d'utilisation. Toutes les demandes effectuées à l'aide de votre clé API seront considérées comme faites en votre nom. Lors de la génération d'une nouvelle clé API, toutes les clés créées précédemment cesseront de fonctionner. Il faudra remplacer la clé dans tous les systèmes qui l'utilisent.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IS_NOT_ENTITY_FOR_PRICES","Il n'y a pas d'entité juridique dans le système comptable. Il n'y a aucune information sur votre entité juridique dans notre système comptable. L'accès aux tarifs n'est disponible que s'il existe une personne morale active. Contactez votre responsable pour corriger l'erreur.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"LINKS_TO_PRICE_BACKWARD","Liens vers des listes de prix avec rétrocompatibilité");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"ATTENTION_DIRECT_LINKS","\"Attention! Les liens de téléchargement direct contiennent votre clé API sous forme non cryptée. Ne partagez pas ces liens publiquement et ne les partagez pas avec quiconque autre que les spécialistes techniques engagés dans l'intégration du catalogue. Ayant accès à votre clé, il est possible de traiter des transactions et des expéditions. de votre personne morale.\"");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"IF_FOR_SOME_REASON_NEW_LINKS","Si pour une raison quelconque les nouveaux liens de téléchargement des listes de prix ne vous conviennent pas, utilisez les liens du tableau ci-dessous. Le format et le contenu sont entièrement conformes aux anciennes grilles de prix. Dans les anciennes listes de prix, il n'est pas possible de sélectionner les marchandises uniquement en fonction de leur disponibilité, d'exclure la TVA du coût des marchandises et les conditions personnelles du contrat de votre personne morale ne sont pas prises en compte. Si vous souhaitez profiter de la nouvelle fonctionnalité, accédez aux options ci-dessous.");
