INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICE_FULL_YML_TEXT","Contient des informations complètes sur l'article. Type personnalisé de description de l'offre de produit (vendor.model).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICE_FULL_RETAIL_CSV_TEXT","<p>Contient les informations <b>maximales</b> sur le produit disponibles dans un type de description personnalisé (vendor.model). Type de prix - <b>vente au détail recommandée</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICE_FULL_SUPERVIP_CSV_TEXT","<p>Contient les informations <b>maximales</b> sur le produit disponibles dans un type de description personnalisé (vendor.model). Type de prix - <b>revendeur</b>.</p>");
