INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICE_TO_GET_DIRECT_LINK","Vous devez disposer d'un compte avec le rôle «Superviseur» afin d'obtenir des liens directs pour télécharger les listes de prix. Si vous n'avez pas de compte avec ce rôle, contactez votre responsable. Si vous avez seulement besoin d'obtenir des liens directs pour son utilisation ultérieure et que votre entreprise dispose d'un compte «Superviseur», contactez son propriétaire.");
