INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_AVAIL","Disponibilité: En stock. Prend les valeurs <b>true</b> si le produit est disponible dans l'entrepôt spécifié, sinon <b>false</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_DESC","Description de l'offre de produits.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_PURCHASE_TYPE","Type d'achat. Peut prendre les valeurs:<br/> <ul> <li><b>'en stock'</b> - l'article est en stock au moins dans l'un des entrepôts sélectionnés</li> <li><b>' en route'</b> - l'article est dans la livraison la plus proche de l'entrepôt à Moscou</li> <li><b>'sur demande'</b> - les marchandises peuvent être amenées à l'entrepôt à Moscou sur demande. <b>Conditions particulières de paiement</b> - à vérifier auprès du responsable.</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_DELIVERY_TIME","Délai de livraison des articles sur demande à l'entrepôt de Moscou, jours. Peut prendre les valeurs:<br> <ul> <li><b>nombre (jours)</b></li> <li><b>'plus disponible'</b> - les livraisons sont arrêtées,</ li> <li><b>'check'</b> - vérifier auprès du responsable,</li> <li>ligne vide - si le délai de livraison n'est pas défini</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_VENDOR","Fabricant ou marque (marque déposée).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_COUNTRY","Pays d'origine de l'article.");
