INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_SUPPLYDATE","Date de la prochaine livraison des articles à l'entrepôt de Moscou");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_SUPPLYQUANTITY","La quantité d'articles disponibles à la commande lors de la prochaine livraison à l'entrepôt de Moscou.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_STANDART","Éléments standards");
