INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_URL","L'URL de la page de l'article sur le portail.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_PRICE","Prix marchand de l'article. Toujours en roubles.");
