INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_CATEGORYID","Identifiant de la catégorie de produit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_PICTURE","Lien vers l'image de l'offre de produits correspondante.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_TYPEPREFIX","Type ou catégorie de produit. Prend la valeur <b>non définie</b> si elle n'est pas définie.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_MODEL","Modèle et paramètres importants (par exemple, index du modèle, fonctionnalités de modification, etc.). Prend la valeur <b>non définie</b> si elle n'est pas définie.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_SALES_NOTES","L'élément permet d'afficher les informations sur:<br> <ul> <li>la nécessité de préciser le délai de livraison avec le responsable;</li> <li>la résiliation de l'achat de l'article (nous ne livrons pas l'article article plus).</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_DELIVERY_OPTIONS","Délai de livraison <b>pour les articles sur demande</b> à l'entrepôt de Moscou. La valeur est envoyée dans l'attribut <b>days</b>. Il s'affiche uniquement si la livraison est disponible pour l'article.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_WEIGHT","L'élément est conçu pour spécifier le poids de l'article. <b>Le poids est en kilogrammes, emballage compris</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_DIMENSIONS","L'élément est conçu pour préciser les dimensions de l'article (longueur, largeur, hauteur) dans l'emballage. <b>Les dimensions sont en centimètres</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_DELIVERY","Possibilité de livraison. Accepte les valeurs:<br> <ul> <li><b>false</b> — nous n'expédions plus l'article ou vous devez vérifier le délai de livraison avec le responsable;</li> <li><b >true</b> — l'article peut être livré;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"PRICES_D_PICKUP","Possibilité de ramassage. Accepte les valeurs:<br> <ul> <li><b>false</b> — nous ne livrons plus l'article et il est en rupture de stock;</li> <li><b>true</b > - l'article est en stock ou la livraison est possible sur demande, vous pouvez réserver l'article sélectionné et le récupérer par vous-même ;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"NON_STANDART","Éléments non standards");
