INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_BRANDMANAGER_TEXT","Vous avez accès à la section des requêtes sur votre marque. Uniquement pour les marques privées: gestion de votre catalogue de marques sur imex.gkrp.local, confirmation des droits de téléchargement de fichiers, envoi d'informations au lead manager concernant la confirmation sur le portail de l'utilisateur inscrit sur votre site. Consultez les prix de toutes les listes de prix, incl. UE.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_ZIPMANAGER_TEXT","Vous avez accès à la visualisation des transactions et informations associées dans le sens des ventes \"pièces détachées\", à toutes les réclamations, à la consultation de toutes les grilles de prix.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_QUALITYMANAGER_TEXT","Vous avez accès à toutes les requêtes relatives aux transactions, réclamations et réclamations.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_SENIORZIPMANAGER_TEXT","Vous pouvez visualiser les transactions et les informations associées dans le sens des ventes de pièces détachées, toutes les réclamations, consulter toutes les listes de prix, éditer les employés de votre service ; envoyer des informations au lead manager sur la confirmation de l'utilisateur sur le portail, s'il s'agit de votre client; enregistrement des transactions pour le compte de la contrepartie, direction des ventes de pièces détachées.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_SENIORQUALITYMANAGER_TEXT","Vous avez accès à toutes les transactions, réclamations, toutes requêtes (ajouts) sur réclamations. Édition des employés de votre service.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_SENIORCOMPLAINTMANAGER_TEXT","Vous avez accès à toutes les transactions, réclamations, toutes requêtes (ajouts) sur réclamations. Édition des employés de votre service.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_COMPLAINTMANAGER_TEXT","Vous avez accès aux claims pour lesquels vous avez été assigné à titre d'ingénieur responsable.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"GROUP_HEADBRANDMANAGER_TEXT","Vous avez accès à la rubrique de requêtes sur votre marque et à la rédaction de vos collaborateurs. Uniquement pour les marques privées: gestion de votre catalogue de marques sur imex.gkrp.local, confirmation des droits de téléchargement de fichiers, envoi d'informations au lead manager concernant la confirmation sur le portail de l'utilisateur inscrit sur votre site ; consulter les prix dans toutes les listes de prix, incl. UE.");
