INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_NAME","Saisissez le nom du produit à afficher dans le catalogue. Si un tel produit existe déjà dans le catalogue, son nom peut ne pas apparaître dans le catalogue. Changer le champ entraînera une modération répétée du produit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_BRAND","Entrez la marque du produit. Si un tel produit existe déjà dans le catalogue, les marques des produits doivent correspondre. Changer le champ entraînera une nouvelle modération du produit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_CATEGORY","Sélectionnez la catégorie de produits à afficher dans le catalogue. Si un tel produit existe déjà dans le catalogue, les catégories de produits doivent correspondre. Changer le champ entraînera une nouvelle modération du produit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_CODE_1C","Rempli uniquement si un tel produit existe déjà dans le catalogue. Dans le cas contraire, le champ doit rester vide.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_PRICE","Saisissez le prix du produit sans préciser la devise.");
