INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_QUANTITY_IN_PACKAGE","Si le produit est vendu dans un emballage (set) - entrez la quantité de produit dans 1 emballage. Si le champ n'est pas renseigné, il est automatiquement compté pour 1 article par colis.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_FBS","Saisissez la quantité du produit que vous souhaitez vendre à l'aide du système FBS. Ne remplissez pas ce champ si vous ne souhaitez pas vendre de produits via le système FBS.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_DELIVERY_TIME","Saisissez le nombre de jours pendant lesquels les marchandises objet de la commande arriveront à votre entrepôt (lors du calcul de la livraison au client, le délai de livraison de votre entrepôt à l'entrepôt Equip sera pris en compte). Ne remplissez pas ce champ si vous ne souhaitez pas vendre de produits sur commande.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_DESCRIPTION","Saisissez la description du produit. Si un tel produit existe déjà dans le catalogue, la description peut ne pas être affichée dans la fiche produit. Changer le champ entraînera une nouvelle modération du produit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1, 5,"TOOLTIP_LENGTH","Saisissez la longueur du produit sans emballage en millimètres. Changer le champ entraînera une nouvelle modération du produit.");
